<script setup lang="ts">import type{ApiSuccess}from'~/types/api';const route=useRoute();type Detail={kind:string;slug:string;title:string;excerpt:string|null;body:string;heroImageUrl:string|null;gallery:string[];publishedAt:string|null;updatedAt:string};const{data,error}=await useFetch<ApiSuccess<Detail>>(`/api/public/content/${String(route.params.slug)}`);if(error.value)throw createError({statusCode:404,statusMessage:'Publication introuvable'});const item=computed(()=>data.value?.data);useHead(()=>({title:item.value?.title||'Publication'}));</script>
<template><article v-if="item" class="section"><div class="container article"><p class="eyebrow">{{item.kind}}</p><h1 class="display-title">{{item.title}}</h1><p v-if="item.excerpt" class="lead">{{item.excerpt}}</p><img v-if="item.heroImageUrl" class="hero-image" :src="item.heroImageUrl" alt=""><div class="body">{{item.body}}</div><p v-if="item.publishedAt" class="muted">Publié le {{new Date(item.publishedAt).toLocaleDateString('fr-FR')}}</p></div></article></template>
<style scoped>.article{max-width:900px}.hero-image{width:100%;max-height:480px;object-fit:cover;border-radius:24px;margin:30px 0}.body{white-space:pre-wrap;font-size:1.06rem;line-height:1.75;margin:38px 0}</style>
